import{_ as t}from"./chunks/hotel.CGP_f0Jj.js";import{_ as a,o as n,c as i,a5 as r}from"./chunks/framework.bIR-4glx.js";const m=JSON.parse('{"title":"Writing: From Draft to Verifiable Revision","description":"Begin with a real audience and unaided draft, then train intention, facts, structure, register, feedback uptake, translation boundaries, AI collaboration, asynchronous handover, and authorship responsibility.","frontmatter":{"title":"Writing: From Draft to Verifiable Revision","description":"Begin with a real audience and unaided draft, then train intention, facts, structure, register, feedback uptake, translation boundaries, AI collaboration, asynchronous handover, and authorship responsibility.","updated":"2026-10-19T00:00:00.000Z","sources_checked":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/part-1/6-writing.md","filePath":"en/threads/part-1/6-writing.md","lastUpdated":1792368000000}'),s={name:"en/threads/part-1/6-writing.md"};function o(d,e,l,c,h,p){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="writing-from-draft-to-verifiable-revision" tabindex="-1">Writing: From Draft to Verifiable Revision <a class="header-anchor" href="#writing-from-draft-to-verifiable-revision" aria-label="Permalink to &quot;Writing: From Draft to Verifiable Revision&quot;">​</a></h1><p>This guide began in 2017. I wanted to share how I learned English and wrote down experiences with vocabulary, listening, reading, and speaking. A friend later joked that I was &quot;the Markdown engineer with many stars.&quot; Between relationships, startups, failure, and disruption, however, writing also stopped.</p><p>After returning, I began to understand writing differently. It is not decoration applied to thought. It turns what one person wants another to understand, verify, decide, or continue into a form that can work after the author leaves.</p><p>I once wanted to remove the writing chapter because I did not feel successful enough to write one. A piece about a failed startup then received specific, thoughtful responses. Writing, I realised, need not wait for triumph. It can preserve what a person knew, misjudged, and carried at the time, allowing failure to face fact and readers after emotion recedes.</p><p><img src="'+t+`" alt="A real scene from the resort hotel project" loading="lazy" decoding="async" width="800" height="522"></p><p>This chapter does not train paragraphs that sound like a model. It offers a traceable path: define audience and task, preserve an unpolished first draft, revise facts, structure, sentences, register, and delivery separately, record reasons for changes, let a reader retell or act, then change topic and audience to test transfer.</p><h2 id="chapter-at-a-glance" tabindex="-1">Chapter at a Glance <a class="header-anchor" href="#chapter-at-a-glance" aria-label="Permalink to &quot;Chapter at a Glance&quot;">​</a></h2><ul><li>Define audience, task, acceptance, and authorship responsibility before choosing form.</li><li>Preserve a timed unaided draft instead of allowing translation or AI to cover the starting point.</li><li>Separate facts, sources, inference, personal experience, and judgments waiting for evidence.</li><li>Give every paragraph a job before polishing sentences and style.</li><li>Use translation to compare meaning, never to decide tone, responsibility, and fact for the author.</li><li>Record accepted and rejected feedback with reasons, not only the final draft.</li><li>Use AI for diagnosis, reader simulation, and variation, not fabrication, authorship, or accountability.</li><li>Treat email, status, decision record, and cross-time-zone handover as complete writing tasks.</li><li>Track one real situation, one raw draft, and one parallel delivery for fourteen days.</li></ul><h2 id="_1-define-the-writing-task" tabindex="-1">1. Define the Writing Task <a class="header-anchor" href="#_1-define-the-writing-task" aria-label="Permalink to &quot;1. Define the Writing Task&quot;">​</a></h2><p>&quot;Write a piece&quot; may require very different structures:</p><table tabindex="0"><thead><tr><th>Task</th><th>Condition</th><th>Evidence of completion</th></tr></thead><tbody><tr><td>Explain</td><td>Audience lacks context; 300-600 words</td><td>Reader can retell the point, evidence, and next step</td></tr><tr><td>Request</td><td>Relationship, resource, and deadline are clear</td><td>Reader knows what to do, when, and how to refuse or confirm</td></tr><tr><td>Status update</td><td>No meeting supplement; asynchronous reader</td><td>Reader knows completed work, risk, block, owner, and next checkpoint</td></tr><tr><td>Decide</td><td>At least two options with cost and deadline</td><td>Decision-maker sees evidence, cost, unknowns, recommendation, and exit</td></tr><tr><td>Narrate</td><td>One concrete event without inventing another mind</td><td>Timeline is clear; fact, feeling, inference, and later interpretation differ</td></tr><tr><td>Reflect</td><td>Revisit experience while separating then and now</td><td>Text proposes a testable next step rather than turning outcome into fate</td></tr><tr><td>Handover</td><td>Next operator was not present</td><td>They can continue, inspect, and roll back using the document alone</td></tr></tbody></table><p>Before drafting, write four sentences: who reads, what they need to understand or complete, what evidence supports it, and which fact, privacy, permission, and responsibility boundaries cannot be crossed.</p><p>Use the <a href="./../../templates/writing-evidence">Writing Evidence Card</a> to keep task, draft, sources, feedback, revision reasons, delivery, and delayed retest together.</p><h2 id="_2-preserve-an-unpolished-draft" tabindex="-1">2. Preserve an Unpolished Draft <a class="header-anchor" href="#_2-preserve-an-unpolished-draft" aria-label="Permalink to &quot;2. Preserve an Unpolished Draft&quot;">​</a></h2><p>Choose a real task and complete a first version in 15-25 minutes. You may write three to five keywords or a simple outline, but do not look up whole-sentence translations, ask AI to write, or delete failed paragraphs.</p><p>Record:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real audience and relationship:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Task, genre, and completion standard:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Length and time limit:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dictionary, translation, sources, and AI allowed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Facts requiring verification:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Privacy, copyright, confidentiality, and authorship boundary:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Raw draft location:</span></span></code></pre></div><p>The draft matters because it shows how you choose content, structure, and language before later support. When the first version comes directly from machine translation or a model, later comparison covers the ability that should have been observed.</p><p>Before revising, state the one sentence the reader should remember, the fact you trust least, and the gap most likely hidden by attractive prose.</p><h2 id="_3-build-a-fact-and-responsibility-ledger" tabindex="-1">3. Build a Fact and Responsibility Ledger <a class="header-anchor" href="#_3-build-a-fact-and-responsibility-ledger" aria-label="Permalink to &quot;3. Build a Fact and Responsibility Ledger&quot;">​</a></h2><p>Writing can change decisions, relationships, and resources. Separate content by evidence type:</p><table tabindex="0"><thead><tr><th>Content</th><th>Minimum record</th><th>Common risk</th></tr></thead><tbody><tr><td>Verifiable fact</td><td>Primary source, version, date, and context</td><td>Staleness, quotation outside context, or distorted retelling</td></tr><tr><td>Number/comparison</td><td>Definition, sample, time range, and baseline</td><td>Missing denominator, selection, or false precision</td></tr><tr><td>Quotation</td><td>Original, speaker, location, and permission</td><td>Changed stance, wrong attribution, or rights breach</td></tr><tr><td>Personal experience</td><td>What was known then and learned later</td><td>Memory presented as a complete record or luck as a rule</td></tr><tr><td>Inference/advice</td><td>Reasoning chain, assumptions, risk, and counterexample</td><td>Judgment disguised as fact</td></tr><tr><td>Information about others</td><td>Minimum necessary scope and clear permission</td><td>Identity exposure or invented inner life</td></tr></tbody></table><p>Keep a source ledger with claim, location, check date, confidence, publication permission, and evidence that would change it. Personal experience can be written without an external citation, but its evidence level still needs an honest name.</p><h2 id="_4-give-every-paragraph-a-job" tabindex="-1">4. Give Every Paragraph a Job <a class="header-anchor" href="#_4-give-every-paragraph-a-job" aria-label="Permalink to &quot;4. Give Every Paragraph a Job&quot;">​</a></h2><p>Writer&#39;s block is often not missing vocabulary but an undecided relationship between information. Start with a small skeleton:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Problem facing the reader:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">My direct answer:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Two or three supports:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One concrete example or minimum fact:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Limit, counterexample, or unknown:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Reader&#39;s next step:</span></span></code></pre></div><p>Label each paragraph: context, problem, claim, reason, evidence, example, turn, limit, request, decision, or handover. Split a paragraph doing four jobs; merge or remove three paragraphs doing one.</p><p>Narrative also needs structure, but not a success template. State what happened, what was known, what you did, what followed, and how you interpret it now. STAR and similar frames should not manufacture victory. An unsuccessful result can remain a credible story.</p><h2 id="_5-translation-is-not-authorship-compare-meaning" tabindex="-1">5. Translation Is Not Authorship: Compare Meaning <a class="header-anchor" href="#_5-translation-is-not-authorship-compare-meaning" aria-label="Permalink to &quot;5. Translation Is Not Authorship: Compare Meaning&quot;">​</a></h2><p>Your strongest language can locate intention and complex concepts. Translation can expose differences. The problem begins when a translated version becomes a final text without author judgment.</p><table tabindex="0"><thead><tr><th>What I mean</th><th>My English first draft</th><th>Decision after comparison</th></tr></thead><tbody><tr><td>Fact, relationship, stance, and next step</td><td>Current unaided version</td><td>Meaning lost, strengthened, weakened, or invented</td></tr></tbody></table><p>Check whether translation changes agent and responsibility, exaggerates certainty, alters negation or condition scope, turns politeness into ambiguity, or replaces a cultural/institutional concept with a false equivalent.</p><p>For translation tasks, preserve source version, purpose, audience, glossary, non-equivalent terms, reviewer, and final owner. Natural is not automatically faithful or appropriate to the current register.</p><h2 id="_6-five-revision-passes-one-question-each" tabindex="-1">6. Five Revision Passes, One Question Each <a class="header-anchor" href="#_6-five-revision-passes-one-question-each" aria-label="Permalink to &quot;6. Five Revision Passes, One Question Each&quot;">​</a></h2><p>Do not revise fact, structure, grammar, and punctuation simultaneously. Work in risk order.</p><h3 id="pass-one-task-and-fact" tabindex="-1">Pass One: Task and Fact <a class="header-anchor" href="#pass-one-task-and-fact" aria-label="Permalink to &quot;Pass One: Task and Fact&quot;">​</a></h3><p>Does the text answer the task? Can numbers, dates, people, quotations, and sources be checked? Is a condition required for the reader&#39;s decision missing?</p><h3 id="pass-two-structure-and-evidence" tabindex="-1">Pass Two: Structure and Evidence <a class="header-anchor" href="#pass-two-structure-and-evidence" aria-label="Permalink to &quot;Pass Two: Structure and Evidence&quot;">​</a></h3><p>Does each paragraph have one clear job? Does evidence support the claim? Does the example carry the conclusion? Does the limit arrive before the decision?</p><h3 id="pass-three-sentence-and-meaning" tabindex="-1">Pass Three: Sentence and Meaning <a class="header-anchor" href="#pass-three-sentence-and-meaning" aria-label="Permalink to &quot;Pass Three: Sentence and Meaning&quot;">​</a></h3><p>Are agent, action, time, condition, negation, reference, and certainty clear? Move a recurring meaning-changing structure into the <a href="./../../templates/grammar-evidence">Grammar Evidence Card</a> for delayed testing.</p><h3 id="pass-four-register-and-voice" tabindex="-1">Pass Four: Register and Voice <a class="header-anchor" href="#pass-four-register-and-voice" aria-label="Permalink to &quot;Pass Four: Register and Voice&quot;">​</a></h3><p>Is a change a correction, ambiguity repair, register choice, or style preference? Remove filler without erasing position. Politeness does not hide the request; professionalism does not lengthen the sentence.</p><h3 id="pass-five-delivery-and-boundary" tabindex="-1">Pass Five: Delivery and Boundary <a class="header-anchor" href="#pass-five-delivery-and-boundary" aria-label="Permalink to &quot;Pass Five: Delivery and Boundary&quot;">​</a></h3><p>Check title, subject, format, links, citations, attachments, privacy, copyright, permission, owner, deadline, and rollback. Can the reader continue when the author is offline?</p><p>For each pass, record only one to three changes that most affect the result. Keep before, after, and reason. Do not accept a change you cannot explain automatically.</p><h2 id="_7-move-feedback-into-the-next-draft" tabindex="-1">7. Move Feedback into the Next Draft <a class="header-anchor" href="#_7-move-feedback-into-the-next-draft" aria-label="Permalink to &quot;7. Move Feedback into the Next Draft&quot;">​</a></h2><p>Do not ask only &quot;Is it good?&quot; Give the reviewer a job:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Retell the main point, evidence, and next step first.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mark where you had to guess, evidence is weak, or register mismatches the relationship.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Separate correction, ambiguity, register choice, and style preference.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Do not rewrite the whole text. Name the three issues that most affect the task.</span></span></code></pre></div><p>Decide on each item: accept, partly accept, reject, or defer, with a reason. Readers reveal blind spots but also bring different knowledge, identity, and preference. Feedback is not an order; rejection cannot rely only on pride.</p><p>L2 writing research shows that written corrective feedback and peer feedback can improve particular outcomes under many conditions. Proficiency, genre, time, task, and uptake affect the result. Improving an old draft is easier than independent use in a new task, so feedback must lead to a parallel text.</p><h2 id="_8-ai-is-an-editorial-assistant-not-a-hidden-author" tabindex="-1">8. AI Is an Editorial Assistant, Not a Hidden Author <a class="header-anchor" href="#_8-ai-is-an-editorial-assistant-not-a-hidden-author" aria-label="Permalink to &quot;8. AI Is an Editorial Assistant, Not a Hidden Author&quot;">​</a></h2><p>AI can simulate readers, locate missing context, classify problems, check candidate citations, compare meaning between versions, generate counterexamples, and pose parallel tasks.</p><p>An auditable process:</p><ol><li>Preserve your task card, source ledger, and unaided draft.</li><li>Ask for diagnosis before a full rewrite.</li><li>Require reason, confidence, and possible error for suggestions.</li><li>Rewrite item by item and record acceptance or rejection.</li><li>Check fact, quotation, link, privacy, and register.</li><li>Close AI and complete a parallel task on a new topic.</li><li>Disclose use as required by institution, school, client, or hiring process.</li></ol><p>Models may label acceptable variation as error, invent sources, erase voice, or make a false experience convincing. Never let them fabricate projects, customers, responsibilities, data, or outcomes. Do not use them to complete exams, applications, or take-home work where external assistance is prohibited.</p><p>Average results from automated-writing-evaluation research support the possibility that tools aid feedback. They do not prove that a polished model sentence improved author ability. The test remains whether you can explain each change and complete a new task after the tool closes.</p><h2 id="_9-asynchronous-writing-must-keep-work-moving" tabindex="-1">9. Asynchronous Writing Must Keep Work Moving <a class="header-anchor" href="#_9-asynchronous-writing-must-keep-work-moving" aria-label="Permalink to &quot;9. Asynchronous Writing Must Keep Work Moving&quot;">​</a></h2><p>Remote work often has no immediate meeting to fill gaps. A useful update can follow:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One-sentence conclusion:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Completed work and evidence location:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current risk/block:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Who must decide what, by when:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next step and owner:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What happens if no response arrives:</span></span></code></pre></div><p>Subject lines such as <code>[Decision by 15:00 UTC]</code>, <code>[Blocked]</code>, and <code>[FYI]</code> should route attention without inventing urgency. Test attachment, link, and permission before sending.</p><p>A handover includes current state, verified facts, unfinished work, failure/rollback, environment/version, owner, and next checkpoint. Writing reduces collaboration&#39;s dependence on the author being online.</p><h2 id="_10-honest-titles-citation-and-authorship" tabindex="-1">10. Honest Titles, Citation, and Authorship <a class="header-anchor" href="#_10-honest-titles-citation-and-authorship" aria-label="Permalink to &quot;10. Honest Titles, Citation, and Authorship&quot;">​</a></h2><p>A title may carry tension but cannot promise what the text does not deliver. Citation lets the reader return to the original location; paraphrase cannot erase another person&#39;s contribution. In collaborative writing, agree who supplied material, drafted, verified, approved, and owns the final result.</p><p>A signature means: I will name whose words these are, what supports them, who may be affected, and what remains uncertain. AI, editors, and peers may participate, but the publisher cannot leave responsibility inside a tool window.</p><p>I want to remain an honest writer: allow an imperfect version and later correction, but do not mislead or let fluency hide missing evidence.</p><h2 id="_11-a-fourteen-day-writing-experiment" tabindex="-1">11. A Fourteen-Day Writing Experiment <a class="header-anchor" href="#_11-a-fourteen-day-writing-experiment" aria-label="Permalink to &quot;11. A Fourteen-Day Writing Experiment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Day</th><th>Action</th><th>Evidence</th></tr></thead><tbody><tr><td>1</td><td>Choose a real audience and task; complete a timed draft</td><td>Raw text, conditions, intention, and unknowns</td></tr><tr><td>2</td><td>Build fact and responsibility ledger</td><td>Claims, sources, permission, and confidence</td></tr><tr><td>3</td><td>Label paragraph jobs and document skeleton</td><td>Structure map and deletions</td></tr><tr><td>4</td><td>Compare first-language intention, English draft, and translation</td><td>Meaning changes and decision reasons</td></tr><tr><td>5</td><td>Revise task, fact, and evidence</td><td>Second version and source checks</td></tr><tr><td>6</td><td>Revise sentence, register, and voice</td><td>Before/after plus classification</td></tr><tr><td>7</td><td>Ask a real reader to retell</td><td>Main point, questions, and next step</td></tr><tr><td>8</td><td>Record feedback acceptance and rejection</td><td>Uptake table</td></tr><tr><td>9</td><td>Complete delivery and boundary check</td><td>Links, attachments, permissions, and owner</td></tr><tr><td>10</td><td>Rewrite the same information for a new audience</td><td>Register and structure transfer</td></tr><tr><td>11</td><td>Write the same genre on a new topic</td><td>Vocabulary and content transfer</td></tr><tr><td>12</td><td>Let AI or a peer propose an omission/counterexample</td><td>Verification and rejection reason</td></tr><tr><td>13</td><td>Complete an async update or handover under time pressure</td><td>Real-use result</td></tr><tr><td>14</td><td>Close tools, complete a parallel task, and choose next cycle</td><td>Evidence to keep, adjust, or move on</td></tr></tbody></table><p>Fourteen days is not a writing-fluency deadline. It asks whether, without the familiar draft and immediate polish, after audience or topic changes, you can still deliver a text you are willing to sign and another person can use.</p><h2 id="_12-evidence-that-writing-is-becoming-ability" tabindex="-1">12. Evidence That Writing Is Becoming Ability <a class="header-anchor" href="#_12-evidence-that-writing-is-becoming-ability" aria-label="Permalink to &quot;12. Evidence That Writing Is Becoming Ability&quot;">​</a></h2><ul><li>You can leave your own timed draft instead of only a tool-produced artifact.</li><li>A reader can retell purpose, evidence, limits, and next step.</li><li>You separate fact, source, inference, personal experience, and advice.</li><li>Each paragraph has a job; removing an attractive sentence does not destroy the line.</li><li>You can explain what translation or AI changed in meaning.</li><li>You distinguish correction, ambiguity, register, and style and explain the decision.</li><li>Feedback enters a new text instead of only polishing the old one.</li><li>An asynchronous reader can continue, decide, or roll back without another meeting.</li><li>The method transfers across audience, topic, and genre.</li><li>You accept responsibility for title, citation, privacy, fact, and authorship.</li></ul><p>Writing improvement sometimes means not more beautiful sentences but less guessing by the reader. You know when to provide a fact, admit an unknown, and remove a line serving only self-image. The text begins to work after the author leaves and preserve a self that can be checked after time passes.</p><h2 id="sources-and-boundaries" tabindex="-1">Sources and Boundaries <a class="header-anchor" href="#sources-and-boundaries" aria-label="Permalink to &quot;Sources and Boundaries&quot;">​</a></h2><ul><li><a href="https://doi.org/10.1111/modl.12189" target="_blank" rel="noreferrer">Kang &amp; Han (2015), The Efficacy of Written Corrective Feedback in Improving L2 Written Accuracy</a>: the meta-analysis synthesises 21 studies and reports that written corrective feedback may improve L2 grammatical accuracy, with proficiency, setting, and genre among the mediating variables.</li><li><a href="https://doi.org/10.1002/tesq.3178" target="_blank" rel="noreferrer">Vuogan &amp; Li (2022), Examining the Effectiveness of Peer Feedback in Second Language Writing</a>: the meta-analysis aggregates 26 studies and reports an overall positive effect, while source comparisons and some moderator conclusions remain limited by the primary-study count.</li><li><a href="https://doi.org/10.1177/07356331221127300" target="_blank" rel="noreferrer">Zhai &amp; Ma (2022), The Effectiveness of Automated Writing Evaluation on Writing Quality</a>: the meta-analysis covers 26 studies and 2,468 participants, reporting average effects and differences by education level, language background, and genre; it does not make every tool output reliable.</li><li>Writing task, genre, audience, institutional rules, copyright, and acceptable AI use change. Important text should return to current facts, primary sources, real readers, and a named accountable owner.</li></ul><p>Related entry points: <a href="./grammar">Grammar</a> | <a href="./4-reading">Reading</a> | <a href="./5-speaking">Speaking</a> | <a href="./7-ai">Learning English with AI</a> | <a href="./8-job-search-english">Job-search English</a> | <a href="./../../templates/writing-evidence">Writing Evidence Card</a> | <a href="./../part-3/4-artifacts-and-delivery">Artifacts</a></p><h2 id="closing-write-the-version-you-are-willing-to-sign" tabindex="-1">Closing: Write the Version You Are Willing to Sign <a class="header-anchor" href="#closing-write-the-version-you-are-willing-to-sign" aria-label="Permalink to &quot;Closing: Write the Version You Are Willing to Sign&quot;">​</a></h2><p>The world is noisy enough. Writing can preserve a quiet place where life remains visible and a judgment continues to face fact, readers, and time after its first emotion has passed.</p><p>A draft records what you could think then. Revision records whether you allowed new evidence and another person&#39;s understanding to change you. The writing need not become perfect at once, but every version prepared for delivery should answer more honestly: whose words are these, what supports them, who may be affected, and what remains uncertain?</p><p>If you do not know where to begin, write a real email, an explanation, or a 200-word note. Give it to one person and ask what they understood. Revise until you are willing to sign it, carry its consequences, and open it again in the future.</p>`,79)])])}const f=a(s,[["render",o]]);export{m as __pageData,f as default};
